      "entities": [
        "AMZN"
      ],
      "claim_period": "April 29, 2026 disclosure; 2027 ramp",
      "citation": {
        "source_id": "amzn-2026-04-29-release",
        "quote": "Secured a commitment from OpenAI to consume approximately two gigawatts (GW) of Trainium capacity through AWS infrastructure to power its frontier models and advanced workloads, which begins ramping in 2027."
      }
    },
    {
      "statement": "Alphabet disclosed external TPU agreements, with most associated revenue expected in 2027; these are sales rather than its own capex purchases.",
      "entities": [
        "GOOGL"
      ],
      "claim_period": "Q2 2026 disclosure; expected 2027 revenue",
      "citation": {
        "source_id": "web-fb40041ca0",
        "quote": "We have signed a limited number of agreements to supply TPU systems to customers who require or provide on-premises infrastructure for specialized, high-scale workloads. In the second quarter of 2026, we began recognizing revenues from these agreements, with the significant majority to be recognized in 2027."
      }
    },
    {
      "statement": "Alphabet’s approximately 60% server/network equipment proportion describes an asset stock, not incremental accelerator spending.",
      "entities": [
        "GOOGL"
      ],
      "claim_period": "December 31, 2025 and June 30, 2026",
      "citation": {
        "source_id": "web-fb40041ca0",
        "quote": "As of December 31, 2025 and June 30, 2026, approximately 60% of technical infrastructure assets were comprised of servers and network equipment."
      }
